mapper.select:
SELECT COALESCE(MAX(step_number), 0) + 1
FROM agent_run_step
WHERE agent_run_id = #{runId}

mapper.update:
UPDATE agent_run_step
SET model_call_id = #{modelCallId},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND status = 'RUNNING'

UPDATE agent_run_step
SET tool_call_id = #{toolCallId},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND status = 'RUNNING'

UPDATE agent_run_step
SET status = 'CANCELLED',
    finished_at = #{finishedAt},
    updated_at = #{finishedAt}
WHERE agent_run_id = #{runId}
  AND status IN ('PENDING', 'RUNNING', 'WAITING_CONFIRMATION')
